def generate(
    prompt = (prompt or "").strip()
    aspect = resolve_aspect_ratio(aspect_ratio)
    if not prompt:
        return error_response(
            error="Prompt is required and must be a non-empty string",
            error_type="invalid_argument",
            provider="openai",
            aspect_ratio=aspect,
        )
    if not os.environ.get("OPENAI_API_KEY"):
        return error_response(
            error=(
                "OPENAI_API_KEY not set. Run `hermes tools` → Image "
                "Generation → OpenAI to configure, or `hermes setup` "
                "to add the key."
            ),
            error_type="auth_required",
            provider="openai",
            aspect_ratio=aspect,
        )
    try:
        pass
    except ImportError:
        return error_response(
            error="openai Python package not installed (pip install openai)",
            error_type="missing_dependency",
            provider="openai",
            aspect_ratio=aspect,
        )
    tier_id, meta = _resolve_model()
    size = _SIZES.get(aspect, _SIZES["square"])
    sources: List[str] = []
    if isinstance(image_url, str) and image_url.strip():
        sources.append(image_url.strip())
    for ref in (normalize_reference_images(reference_image_urls) or []):
        sources.append(ref)
    sources = sources[:16]  # gpt-image-2 edit caps at 16 images
    is_edit = bool(sources)
    modality = "image" if is_edit else "text"
    client = openai.OpenAI()
    if is_edit:
        try:
            files = []
            for ref in sources:
                data, fname = _load_image_bytes(ref)
                bio = io.BytesIO(data)
                bio.name = fname
                files.append(bio)
        except Exception as exc:
            return error_response(
                error=f"Could not load source image for editing: {exc}",
                error_type="io_error",
                provider="openai",
                model=tier_id,
                prompt=prompt,
                aspect_ratio=aspect,
            )
        try:
            response = client.images.edit(
                model=API_MODEL,
                image=files if len(files) > 1 else files[0],
                prompt=prompt,
                size=size,  # type: ignore[arg-type]  # _SIZES values are valid gpt-image sizes
                quality=meta["quality"],
                n=1,
            )
        except Exception as exc:
            return error_response(
                error=f"OpenAI image editing failed: {exc}",
                error_type="api_error",
                provider="openai",
                model=tier_id,
                prompt=prompt,
                aspect_ratio=aspect,
            )
    else:
        payload: Dict[str, Any] = {
            "model": API_MODEL,
            "prompt": prompt,
            "size": size,
            "n": 1,
            "quality": meta["quality"],
        }
        try:
            response = client.images.generate(**payload)
        except Exception as exc:
            return error_response(
                error=f"OpenAI image generation failed: {exc}",
                error_type="api_error",
                provider="openai",
                model=tier_id,
                prompt=prompt,
                aspect_ratio=aspect,
            )
    data = getattr(response, "data", None) or []
    if not data:
        return error_response(
            error="OpenAI returned no image data",
            error_type="empty_response",
            provider="openai",
            model=tier_id,
            prompt=prompt,
            aspect_ratio=aspect,
        )
    first = data[0]
    b64 = getattr(first, "b64_json", None)
    url = getattr(first, "url", None)
    revised_prompt = getattr(first, "revised_prompt", None)
    if b64:
        try:
            saved_path = save_b64_image(b64, prefix=f"openai_{tier_id}")
        except Exception as exc:
            return error_response(
                error=f"Could not save image to cache: {exc}",
                error_type="io_error",
                provider="openai",
                model=tier_id,
                prompt=prompt,
                aspect_ratio=aspect,
            )
        image_ref = str(saved_path)
    elif url:
        try:
            saved_path = save_url_image(url, prefix=f"openai_{tier_id}")
        except Exception as exc:
            image_ref = url
        else:
            image_ref = str(saved_path)
    else:
        return error_response(
            error="OpenAI response contained neither b64_json nor URL",
            error_type="empty_response",
            provider="openai",
            model=tier_id,
            prompt=prompt,
            aspect_ratio=aspect,
        )
    extra: Dict[str, Any] = {"size": size, "quality": meta["quality"]}
    if revised_prompt:
        extra["revised_prompt"] = revised_prompt
    return success_response(
        image=image_ref,
        model=tier_id,
        prompt=prompt,
        aspect_ratio=aspect,
        provider="openai",
        modality=modality,
        extra=extra,
    )

