def flush_all(self) -> None:
    if self._async_queue is not None:
        while not self._async_queue.empty():
            try:
                item = self._async_queue.get_nowait()
                if item is not _ASYNC_SHUTDOWN:
                    self._flush_session(item)
            except queue.Empty:
                pass

